<?php
require "../config/db.php";require "auth.php";$id=(int)($_GET['id']??0);$edit=$id>0;
$r=['attraction_id'=>'','name'=>'','location'=>'','estimated_spending'=>'','description'=>''];
if($edit){$s=$pdo->prepare("SELECT * FROM restaurants WHERE restaurant_id=?");$s->execute([$id]);$r=$s->fetch();}
if($_SERVER['REQUEST_METHOD']==='POST'){if($edit){$pdo->prepare("UPDATE restaurants SET attraction_id=?,name=?,location=?,estimated_spending=?,description=? WHERE restaurant_id=?")->execute([$_POST['attraction_id']?:null,$_POST['name'],$_POST['location'],$_POST['estimated_spending']?:null,$_POST['description'],$id]);}else{$pdo->prepare("INSERT INTO restaurants(attraction_id,name,location,estimated_spending,description) VALUES(?,?,?,?,?)")->execute([$_POST['attraction_id']?:null,$_POST['name'],$_POST['location'],$_POST['estimated_spending']?:null,$_POST['description']]);}header("Location: restaurants.php");exit;}
$ats=$pdo->query("SELECT attraction_id,name FROM attractions ORDER BY name")->fetchAll();$pageTitle=$edit?"Edit Restaurant":"Add Restaurant";include "header.php";?>
<section class="section container"><div class="form-card"><h1><?=$pageTitle?></h1><form method="post"><div class="form-group"><label>Related Attraction</label><select class="form-control" name="attraction_id"><option value="">None</option><?php foreach($ats as $x):?><option value="<?=$x['attraction_id']?>" <?=$r['attraction_id']==$x['attraction_id']?'selected':''?>><?=htmlspecialchars($x['name'])?></option><?php endforeach;?></select></div><?php foreach(['name'=>'Name','location'=>'Location','estimated_spending'=>'Estimated Spending','description'=>'Description'] as $f=>$label):?><div class="form-group"><label><?=$label?></label><?php if($f==='description'):?><textarea class="form-control" name="<?=$f?>" rows="4"><?=htmlspecialchars($r[$f])?></textarea><?php else:?><input class="form-control" name="<?=$f?>" value="<?=htmlspecialchars($r[$f])?>" required="<?=$f==='name'?'required':''?>"><?php endif;?></div><?php endforeach;?><button class="btn">Save</button> <a class="btn secondary" href="restaurants.php">Cancel</a></form></div></section>
<?php include "footer.php"; ?>